library(mgcv);library(jsonlite);a<-commandArgs(TRUE);p<-fromJSON(a[1]);d<-as.data.frame(p$data);d$bound<-as.numeric(d$bound);calls<-list();trace('gam.fit4',where=asNamespace('mgcv'),print=FALSE,tracer=quote(.params<-sp),exit=quote({v<-returnValue();calls[[length(calls)+1]]<<-list(params=.params,coef=v$coefficients,score=v$REML,deriv=deriv,theta=family$getTheta())}));b<-gam(as.formula(p$formula),data=d,family=cnorm(),weights=d$w,scale=2,method='REML');write_json(list(coef=coef(b),theta=b$family$getTheta(),sp=b$sp,score=b$gcv.ubre,outer=b$outer.info,calls=calls),a[2],digits=17,auto_unbox=TRUE)
